"use strict";
let academicCatalog=null,academicContext=null,academicRoute=null,academicTab='drafts',academicDraft=null,academicReviewData=null,academicBusy=false,academicJobTimer=null;
const c7=(operation,payload={},peer_id=null,request_id=uid())=>api('/api/local/capabilities/invoke',{contract_version:'companion.capability.v7',operation,payload,peer_id,request_id});
const academicPeer=()=>workspaceTeacher()?selectedPeer:null;
const academicLines=s=>String(s||'').split(/\n/).map(s=>s.trim()).filter(Boolean);
const academicKinds=['grammar_mcq','reading_mcq','listening'];
const academicOptions=(values,current)=>Object.entries(values).map(([id,label])=>`<option value="${h(id)}" ${current===id?'selected':''}>${h(typeof label==='string'?label:label.name)}</option>`).join('');
async function academicLoad(){const previous=academicContext?.selection.subject;const space=(await w8('initialize',{},'initialize-subject-workspaces-v1')).data;document.body.dataset.workspace=space.active;academicCatalog=(await c7('academic.catalog')).data;academicContext=(await c7('academic.context')).data;if(previous!==academicContext.selection.subject)continuityCatalog=null;}
const academicPreviousNav=workspaceNavigation;
workspaceNavigation=function(){
    const base=academicPreviousNav();
    const section=WorkspaceState.activeRoute(view,workspaceReturn),childActive=['k12','resources','practice'].includes(section);
    // Learning domains contain their own route menus; specialized subjects are not peer domains.
    const academicDomain=`<div class="workspace-nav-group"><p>学习领域</p><div class="academic-domain-nav"><button data-action="ws-route" data-route="academic" class="${section==='academic'?'active':childActive?'academic-parent-active':''}" ${section==='academic'?'aria-current="page"':''}>学科与路线</button><div id="academic-route-subnav" class="academic-route-subnav" role="group" aria-label="学科与路线的二级菜单"><button data-action="academic-select" data-subject="english" data-track="k12" class="${section==='k12'?'active':''}" ${section==='k12'?'aria-current="page"':''}>${workspaceTeacher()?'K12英语教学':'K12英语学习'}</button><button data-action="academic-select" data-subject="english" data-track="study_abroad" class="${['resources','practice'].includes(section)?'active':''}" ${['resources','practice'].includes(section)?'aria-current="page"':''}>${workspaceTeacher()?'留学英语备题与试听':'留学英语练习'}</button></div></div></div>`;
    const scoped=academicContext?.selection.subject==='english'?academicDomain:academicDomain.replace(/<div id="academic-route-subnav"[\s\S]*?<\/div>/,'');
    return base.replace('<nav aria-label="本机导航" id="workspace-navigation">','<nav aria-label="本机导航" id="workspace-navigation">'+scoped);
};
workspaceRoutes.push('academic','k12');
const academicPreviousRender=workspaceRender;
workspaceRender=async function(route){
    if(route==='academic')return academicSubjects();
    if(route==='k12')return academicHome();
    return academicPreviousRender(route);
};
const academicPreviousBoot=workspaceBoot;
workspaceBoot=async function(){await academicLoad();return academicPreviousBoot();};
const academicPreviousHeader=header;
header=function(){academicPreviousHeader();if(status?.profile?.role&&academicContext){const s=academicContext.selection;const n=document.createElement('button');n.className='academic-header-button';n.dataset.action='ws-route';n.dataset.route='academic';n.textContent='当前学科：'+(academicCatalog?.subjects[s.subject]?.name||'学科')+' / '+(academicCatalog?.subjects[s.subject]?.tracks[s.track]||'选择路线').split('（')[0]+' · 切换';document.querySelector('.workspace-header-tools')?.prepend(n);}};
const academicPreviousSetup=setup;
setup=function(){academicPreviousSetup();const f=$('#setup-form');if(!f)return;f.querySelector('.inline-grid').insertAdjacentHTML('beforebegin',`<div class="inline-grid"><label class="field">学习学科<select name="academic_subject" id="academic-first-subject"><option value="english">英语</option><option value="mathematics">数学</option><option value="science">科学与理科</option><option value="humanities">人文与社会</option><option value="other">其他学科</option></select></label><label class="field">学习路线<select name="academic_track" id="academic-first-track"><option value="k12">K12英语</option><option value="study_abroad">留学英语（托福 / 雅思）</option><option value="materials">英语资料学习</option></select></label></div><p class="small muted">K12与留学英语分别建立教学范围。数学等学科目前使用通用资料学习，不宣称已有专用考试测评。</p>`);academicSetupFields();};
function academicSetupFields(){const s=$('#academic-first-subject'),t=$('#academic-first-track');if(!s||!t)return;if(s.value!=='english')t.innerHTML='<option value="materials">通用资料学习</option>';else if(t.options.length===1)t.innerHTML='<option value="k12">K12英语</option><option value="study_abroad">留学英语（托福 / 雅思）</option><option value="materials">英语资料学习</option>';const legacy=$('#exam')?.closest('.inline-grid');if(legacy)legacy.hidden=!(s.value==='english'&&t.value==='study_abroad');}
function academicTrackContent(subject,track){
    if(subject==='legacy')return {title:'历史工作区（只读）',audience:'旧版原件 · 作业 · 反馈',description:'保留无法可靠自动确定学科的历史记录。明确归属后可迁入资料，其他学科不会混显这些记录。',action:'查看历史记录'};
    if(subject==='english'&&track==='k12')return {title:'K12 英语',audience:'小学 · 初中 · 高中',
        description:workspaceTeacher()?'按年级和实际教材范围准备练习，连接学生的作答、评阅与再测。':'跟随教材和考点练习，完成老师的任务，结合反馈继续学习。',
        action:workspaceTeacher()?'进入 K12 教学':'进入 K12 学习'};
    if(subject==='english'&&track==='study_abroad')return {title:'留学英语',audience:'托福 · 雅思 · 留学准备',
        description:'围绕考试目标和留学阶段，开展个性化英语练习与准备。',action:'进入留学英语'};
    return {title:subject==='english'?'英语资料学习':academicCatalog.subjects[subject].name+'资料学习',audience:'课文 · 讲义 · 笔记',
        description:'从一份自己的资料开始，阅读、提问、完成练习并查看反馈。',action:'进入学科工作区',
        note:subject==='english'?'适合不按考试或教材路线开展的学习。':subject==='mathematics'?'目前提供通用资料学习，专用数学题型与测评尚未接入。':'目前提供通用资料学习，专门的学科评价仍需教师补充。'};
}
function academicSubjectPanel(subject){
    const name=academicCatalog.subjects[subject].name,tracks=Object.keys(academicCatalog.subjects[subject].tracks),selection=academicContext.selection;
    return `<div class="academic-panel-heading"><span class="academic-step">02 / 选择路线</span><h2 id="academic-route-title">${h(name)}${workspaceTeacher()?'教学':'学习'}路线</h2><p>选择适合本次目标的入口。</p></div>
        <div class="academic-track-grid">${tracks.map(track=>{const info=academicTrackContent(subject,track),current=selection.subject===subject&&selection.track===track;
            return `<article class="academic-track-card ${current?'is-current':''} ${track==='materials'?'is-materials':''}"><div class="academic-track-copy"><div class="academic-track-label"><span>${h(info.audience)}</span>${current?'<span class="academic-current-badge">当前路线</span>':''}</div><h3>${h(info.title)}</h3><p>${h(info.description)}</p>${info.note?`<p class="academic-track-note">${h(info.note)}</p>`:''}</div><button class="btn ${current?'accent':'ghost'}" data-action="academic-select" data-subject="${h(subject)}" data-track="${h(track)}">${h(info.action)} <span aria-hidden="true">→</span></button></article>`;
        }).join('')}</div><div class="academic-selection-help"><span>第一次使用？可以先从一份熟悉的资料开始。</span><button class="btn text" data-action="ws-route" data-route="guide">查看使用指南 →</button></div>`;
}
function academicBrowseSubject(subject){
    if(!academicCatalog?.subjects[subject]||!$('#academic-subject-panel'))return;
    document.querySelectorAll('[data-action="academic-browse"]').forEach(button=>{const active=button.dataset.subject===subject;button.classList.toggle('is-selected',active);button.setAttribute('aria-pressed',String(active));});
    $('#academic-subject-panel').innerHTML=academicSubjectPanel(subject);
}
async function academicSubjects(){
    await academicLoad();view='academic';const selection=academicContext.selection,subject=selection.subject,current=academicTrackContent(subject,selection.track);
    shell(`${workspaceHeading('SUBJECT / 学科与路线','选择一个独立的学科工作区。','进入后，只显示这个学科的资料、作业、反馈与学习记录。切换学科不会改变配对关系和模型配置。','<button class="btn ghost" data-action="academic-workspace-new">＋ 添加学科</button>')}
        <div class="academic-selection-current"><span class="academic-current-dot" aria-hidden="true"></span><span>当前路线：<strong>${h(current.title)}</strong></span></div>
        <div class="academic-selection-layout"><section class="academic-subject-picker" aria-labelledby="academic-subject-title"><span class="academic-step">01 / 选择学科</span><h2 id="academic-subject-title">${workspaceTeacher()?'本次教什么？':'想学什么？'}</h2><div class="academic-subject-list">${Object.entries(academicCatalog.subjects).map(([id,item],index)=>`<button class="academic-subject-option ${id===subject?'is-selected':''}" data-action="academic-browse" data-subject="${h(id)}" aria-pressed="${id===subject}"><span class="academic-subject-number" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><span>${h(item.name)}</span><span class="academic-subject-arrow" aria-hidden="true">→</span></button>`).join('')}</div><p class="academic-picker-note">点选学科查看路线，进入后才切换。</p></section><section id="academic-subject-panel" class="academic-subject-panel" aria-labelledby="academic-route-title">${academicSubjectPanel(subject)}</section></div>`);
}
async function academicHome(){
    await workspaceLoad();await academicLoad();view='k12';const peer=academicPeer();const routes=(await c7('route.list',{},peer)).data.routes;
    const remembered=localStorage.getItem('academic-route:'+status.device_id+':'+(peer||'self'));academicRoute=routes.find(r=>r.id===remembered&&!r.archived)||routes.find(r=>!r.archived)||null;
    const pane=academicRoute?await academicPane():'';const notices=workspaceTeacher()?(await c7('k12.notifications')).data.notifications.filter(n=>!n.read):[];
    shell(`${workspaceHeading('ENGLISH / K12','把范围、练习和反馈接起来。','K12教学工程功能；内容与量规仍需教师专业核对。默认保持原答，不把错项类型直接确认成学生原因。')}
        <section class="card"><div class="academic-route-bar">${workspaceTeacher()?`<label>当前学生<select id="academic-peer">${status.peers.filter(p=>p.role==='student'&&p.state==='active').map(p=>`<option value="${h(p.id)}" ${peer===p.id?'selected':''}>${h(p.name)}</option>`).join('')}</select></label>`:''}<label>本次学习路线<select id="academic-route">${routes.filter(r=>!r.archived).map(r=>`<option value="${h(r.id)}" ${r.id===academicRoute?.id?'selected':''}>${h(r.title)} · ${h(academicCatalog.levels[r.level])}${r.grade}年级</option>`).join('')||'<option value="">先建立一条路线</option>'}</select></label><button class="btn ghost" data-action="academic-route-new">＋ 建立路线</button>${academicRoute?'<button class="btn text" data-action="academic-route-edit">调整路线目标</button>':''}</div>${workspaceTeacher()&&!peer?'<p class="academic-note">先在“师生配对”连接学生，再为对应学生建立路线；通用资料仍可先阅读。</p>':''}</section>
        ${notices.length?`<section class="card"><h2>新收到 ${notices.length} 份K12提交</h2>${notices.slice(0,8).map(n=>`<p>${h(status.peers.find(p=>p.id===n.peer_id)?.name||'学生')} · ${h(n.title)} <button class="btn text" data-action="academic-notification" data-id="${h(n.id)}" data-task="${h(n.task_id)}">打开并标为已读</button></p>`).join('')}</section>`:''}${academicRoute?`<div class="academic-tabs">${[['drafts','练习与审题'],['scopes','教材与范围'],['bank','已审题库'],['report','问题与学习报告'],...(workspaceTeacher()?[['classes','班级与批量布置']]:[])].map(([id,name])=>`<button data-action="academic-tab" data-tab="${id}" class="${academicTab===id?'active':''}" aria-pressed="${academicTab===id}">${name}</button>`).join('')}</div>${pane}`:`<section class="card"><h2>从一条清楚的小目标开始</h2><ol class="academic-tour"><li>选择学段和年级，建立自己的教材或考试路线。</li><li>添加实际教材单元范围；不确定教材时，可用明确知识点试练。</li><li>准备原创草稿，审题后布置；学生自主草稿始终标记未审。</li><li>提交后核对错法，必要时追问，再安排新题验证。</li></ol></section>`}
        ${!workspaceTeacher()?`<section class="card"><h2>老师布置的K12任务</h2>${workspaceRows.filter(t=>t.pack.academic&&t.origin==='teacher').map(workspaceTaskRow).join('')||'<p>配对后，老师明确布置的任务会出现在这里和“我的任务”。老师路线与个人自主路线分别保存。</p>'}</section>`:''}
        <details class="card"><summary>第一次使用：照着走一遍</summary><ol><li>建立路线并填写本次小目标。</li><li>在“教材与范围”登记真实来源和单元；词表不完整时，系统只提示待核对词。</li><li>先体验原创示例，或用自己的API准备草稿。</li><li>教师逐题核对答案、歧义与错项，另行确认布置。</li><li>收到提交后，在任务页记录错因假设、验证证据、讲解和主观题评阅。</li><li>目标测验须在布置前确认覆盖；带提示练习不计独立目标测验。</li></ol><p class="small muted">本轮不包含教师经营CRM、课包、排课或招生。录音须自行导入并完整试听；不自动用合成音频替代真人素材。</p></details>`);
}
async function academicPane(){const r=academicRoute,peer=academicPeer();
    if(academicTab==='scopes'){const data=(await c7('scope.list',{route_id:r.id},peer)).data.records;return `<section class="card"><h2>实际教材与单元范围</h2><p>范围来自你有权使用的资料。缺词、词形变化或未核验抽取不能直接算超纲；候选范围与教师核对状态分开。</p><button class="btn accent" data-action="academic-scope-new">＋ 添加单元范围</button>${data.map(s=>`<article class="local-task"><div><h3>${h(s.textbook)} · ${h(s.unit)}</h3><p>${s.words.length}词 · ${s.grammar.length}语法项 · 第${s.revision}版</p><p class="small muted">${s.content_reviewed?'教师声明已核对':'候选，未逐项核验'} · ${s.complete?'本范围完整性由用户声明':'范围可能不完整'} · ${h(s.source)}</p></div><button class="btn ghost" data-action="academic-scope-edit" data-id="${h(s.id)}">查看 / 更新</button></article>`).join('')}<button class="btn ghost" data-action="academic-scope-check">检查一段文字与当前词表</button></section>`;}
    if(academicTab==='report'){const rep=(await c7('k12.report',{route_id:r.id},peer)).data;const gaps=(await c7('k12.replenishment.list',{route_id:r.id},peer)).data.records.filter(x=>x.missing);return `<section class="card"><h2>下一步：${h(rep.next.action)}</h2><p>${h(rep.next.basis)}</p><button class="btn accent" data-action="academic-next">按此建议准备下一次候选</button><p class="small muted">${rep.tasks}项任务 · ${rep.submitted}项有提交 · ${rep.pending_reviews}道主观题待评 · ${rep.unconfirmed_problems}项原因待验证 · ${rep.confirmed_problems}项有教师补充证据声明</p></section><section class="card"><h2>问题记录</h2>${rep.problems.map(p=>`<div class="result-item"><strong>${h(p.question_id)} · ${h(p.state==='supported_cause'?'教师依据补充证据记录':p.state==='hypothesis'?'可能原因，待验证':'错误表现')}</strong><p>${h(p.observation)}</p><p>${h(p.cause||'原因未知')} · ${h(p.selected_trap||'未记录干扰类型')}</p><button class="btn text" data-action="academic-open-work" data-id="${h(p.task_id)}">回到原始作品 →</button></div>`).join('')||'<p>尚无原因记录。自动错题只表示本次表现，不直接确认真实原因。</p>'}</section><section class="card"><h2>目标测验结果</h2>${rep.target_results.map(t=>`<article><strong>本次试行参考线 ${Math.round(t.threshold*100)}%</strong>${t.outcomes.map(o=>`<p>${h(o.target)}：${o.score}/${o.total} · ${h(({pending:'待核对评分、帮助或坏题条件',meets_this_target:'本次目标达到所声明标准',needs_more_evidence:'本次尚需补教与新题验证'})[o.state])}</p>`).join('')}</article>`).join('')||'<p>只有布置前确认覆盖的目标测验才出现在这里，普通练习不追认为测验。</p>'}<p class="small muted">${h(rep.unmeasured)} 不推断长期掌握或官方等级。</p></section><section class="card"><h2>备题缺口</h2>${gaps.map(g=>`<p>需要${g.requested}题，当前可用${g.selected.length}题，还缺${g.missing}题。${h(g.skills.join('、'))}</p>`).join('')||'<p>没有记录到待补库存。当前不会在后台自动生产题目。</p>'}</section>`;}
    if(academicTab==='classes'){const cs=(await c7('k12.class.list')).data.classes;return `<section class="card"><h2>班级不是能力等级</h2><p>布置时冻结名单，逐人核对范围和未见题。失败可重试；不复制目标覆盖确认，不把未交和待评计为零分。</p><button class="btn accent" data-action="academic-class-new">＋ 建立班级</button>${cs.map(c=>`<article class="local-task"><div><h3>${h(c.title)}</h3><p>${c.peers.length}名 · 第${c.revision}版 ${c.archived?'· 已归档':''}</p></div><div class="actions"><button class="btn ghost" data-action="academic-class-edit" data-id="${h(c.id)}">调整名单</button><button class="btn ghost" data-action="academic-class-assign" data-id="${h(c.id)}">布置已审草稿</button><button class="btn text" data-action="academic-class-report" data-id="${h(c.id)}">查看任务报告</button></div></article>`).join('')}<button class="btn ghost" data-action="academic-group-candidates">查看有可比测量依据的分组候选</button></section>`;}
    const bank=academicTab==='bank';const records=(await c7(bank?'k12.bank.list':'k12.draft.list',{route_id:r.id},peer)).data.records;
    return `<section class="card"><h2>${bank?'已审备题，复用前再核对适配':'先准备候选，再逐题审校'}</h2><div class="academic-actions">${bank?'<button class="btn accent" data-action="academic-bank-pick">按考点查未见题库存</button>':'<button class="btn accent" data-action="academic-generate">用自己的API准备草稿</button><button class="btn ghost" data-action="academic-draft-new">手动编写</button><button class="btn ghost" data-action="academic-example">体验原创示例</button><button class="btn ghost" data-action="academic-import">导入JSON草稿</button>'}</div>${records.map(d=>`<article class="local-task"><div><h3>${h(d.body.title)}</h3><p>${d.body.questions.length}题 · 第${d.revision}版 · ${h(d.body.source)}</p><p class="small muted">${bank?'已有教师审题声明，不等于机器证明语义正确':'候选内容，未自动发布或确认掌握'}</p></div><div class="actions"><button class="btn ghost" data-action="academic-draft-edit" data-id="${h(d.id)}">查看与修改</button>${workspaceTeacher()?`<button class="btn ghost" data-action="academic-independent-review" data-id="${h(d.id)}">AI独立审题</button><button class="btn ghost" data-action="academic-review" data-id="${h(d.id)}">逐题审校</button><button class="btn accent" data-action="academic-publish" data-id="${h(d.id)}">布置 / 测验</button>${bank?`<button class="btn text" data-action="academic-retire" data-id="${h(d.id)}">停用备题</button>`:''}`:`<button class="btn accent" data-action="academic-self" data-id="${h(d.id)}">开始本机自练（未审）</button>`}</div></article>`).join('')||'<p>尚无草稿。可以先用原创示例熟悉一次流程。</p>'}</section>`;
}
function academicDialog(title,body){modal(title,body);document.querySelector('.modal').classList.add('academic-modal');}
function academicRouteForm(edit=false){const r=edit?academicRoute:null;if(workspaceTeacher()&&!selectedPeer)throw Error('先连接并选择学生');academicDialog(edit?'调整K12路线':'建立K12英语路线',`<form id="academic-route-form" class="local-form" data-id="${h(r?.id||'')}" data-revision="${r?.revision||0}"><label class="field">路线名称<input name="title" required maxlength="160" value="${h(r?.title||'')}" placeholder="例如：七年级同步学习 / 初中英语阅读"></label><div class="inline-grid"><label class="field">学段<select name="level">${academicOptions(academicCatalog.levels,r?.level||'junior')}</select></label><label class="field">年级（1—12）<input name="grade" type="number" min="1" max="12" value="${r?.grade||7}" required></label><label class="field">路线用途<select name="kind"><option value="curriculum" ${r?.kind!=='exam'?'selected':''}>教材 / 明确考点学习</option><option value="exam" ${r?.kind==='exam'?'selected':''}>考试备考</option></select></label></div><label class="field">当前小目标<textarea name="goal" maxlength="1000" required>${h(r?.goal||'')}</textarea></label><div class="inline-grid"><label class="field">考试或课程名称（选填）<input name="exam_name" maxlength="160" value="${h(r?.exam_name||'')}"></label><label class="field">考试日期（选填）<input name="exam_date" type="date" value="${h(r?.exam_date||'')}"></label><label class="field">每周可学习次数<input name="weekly_sessions" type="number" min="1" max="14" value="${r?.weekly_sessions||2}"></label></div><label class="field">已学到的单元顺序（需人工核对，不因做完练习自动推进）<input name="scope_order" type="number" min="1" max="1000" value="${r?.scope_order||1}"></label>${r?'<label class="checkline"><input name="archived" type="checkbox">归档这条路线（历史保留）</label>':''}<button class="btn accent" type="submit">保存路线</button></form>`);}
async function academicScopeForm(id){const s=id?(await c7('scope.read',{id},academicPeer())).data.record:null;const materials=(await c7('academic.material.list',{subject:'english'})).data.materials;if(s?.material_ref?.material_id&&!materials.some(m=>m.id===s.material_ref.material_id)){const original=(await studyCall('material.read',{material_id:s.material_ref.material_id})).data;materials.unshift({...original,title:original.title+'（历史绑定，学科待核对）'});}academicDialog('登记实际教材范围',`<form id="academic-scope-form" class="local-form" data-id="${h(s?.id||'')}" data-revision="${s?.revision||0}"><div class="inline-grid"><label class="field">教材 / 讲义名称<input name="textbook" required value="${h(s?.textbook||'')}"></label><label class="field">单元名称<input name="unit" required value="${h(s?.unit||'')}" placeholder="例如 Unit 1"></label><label class="field">单元顺序<input name="order" type="number" min="1" max="1000" value="${s?.order||1}"></label></div><label class="field">来源与使用说明<input name="source" required value="${h(s?.source||'')}"></label><label class="field">关联本机原始资料（可选）<select name="material_id"><option value="">暂不关联；仍须明确来源</option>${materials.map(m=>`<option value="${h(m.id)}" ${s?.material_ref?.material_id===m.id?'selected':''}>${h(m.title)}</option>`).join('')}</select></label>${[['words','实际词表（每行一个词形）'],['phrases','短语（每行一项）'],['grammar','本单元语法 / 操作（每行一项）']].map(([key,label])=>`<label class="field">${label}<textarea name="${key}">${h((s?.[key]||[]).join('\n'))}</textarea></label>`).join('')}<label class="checkline"><input name="complete" type="checkbox" ${s?.complete?'checked':''}>我声明此处已完整填写所选范围；这不代表整套课标完整</label>${workspaceTeacher()?`<label class="checkline"><input name="content_reviewed" type="checkbox" ${s?.content_reviewed?'checked':''}>我已逐项核对这些内容与原始来源</label>`:''}<p class="small muted">未核验或不完整词表只提供待确认线索，不直接据此判超纲。</p><button class="btn accent" type="submit">保存本版范围</button></form>`);}
function academicEmptyQuestion(i=0){return {id:'q'+(i+1),type:'grammar_mcq',skill:'',material:'',prompt:'',options:['','',''],key:['A'],evidence:'',explanation:'',traps:{B:'语法形式错误',C:'语法形式错误'},points:1};}
function academicQuestionEditor(q,i){return `<fieldset class="academic-question" data-index="${i}"><legend>第${i+1}题 · ${h(q.id)}</legend><div class="inline-grid"><label class="field">题型<select name="type_${i}">${academicOptions(academicCatalog.types,q.type)}</select></label><label class="field">实际考点<input name="skill_${i}" value="${h(q.skill)}" required maxlength="120"></label><label class="field">本题分值<input name="points_${i}" type="number" min=".1" max="100" step=".1" value="${q.points||1}"></label></div><label class="field">本题原文 / 听力原文<textarea name="material_${i}" maxlength="12000">${h(q.material)}</textarea></label><label class="field">题干或成果要求<textarea name="prompt_${i}" required maxlength="2000">${h(q.prompt)}</textarea></label><div class="inline-grid"><label class="field">选项（每行一项；填空/主观可留空）<textarea name="options_${i}">${h((q.options||[]).join('\n'))}</textarea></label><label class="field">答案（每行一种可接受答案；主观留空）<textarea name="key_${i}">${h((q.key||[]).join('\n'))}</textarea></label></div><label class="field">原文依据或语法依据<input name="evidence_${i}" value="${h(q.evidence)}" maxlength="2000"></label><label class="field">解析<textarea name="explanation_${i}" maxlength="2000">${h(q.explanation)}</textarea></label><details><summary>选择题干扰类型（只保存错误选项；不是学生真实错因）</summary>${'ABCDEF'.split('').map(letter=>`<label class="field">选项${letter}<select name="trap_${i}_${letter}">${academicOptions(Object.fromEntries(academicCatalog.traps.map(x=>[x,x])),q.traps?.[letter]||'语法形式错误')}</select></label>`).join('')}</details></fieldset>`;}
async function academicDraftEditor(id,original){const d=id?(await c7('k12.draft.read',{id},academicPeer())).data.record:null;academicDraft=d;const b=original||d?.body||{title:'',instructions:'按题目和材料作答，保留实际原答。',goal:academicRoute.goal,source:'',criteria:['回应本次问题','依据与过程可核对'],questions:[academicEmptyQuestion()],scope_ids:[],supports:[]};const scopes=(await c7('scope.list',{route_id:academicRoute.id},academicPeer())).data.records;
    academicDialog(d?'查看与修改出题草稿':'准备一份K12草稿',`<form id="academic-draft-form" class="local-form" data-id="${h(d?.id||'')}" data-revision="${d?.revision||0}"><label class="field">标题<input name="title" required value="${h(b.title)}"></label><label class="field">本次目标<input name="goal" required value="${h(b.goal)}"></label><label class="field">作答说明<textarea name="instructions" required>${h(b.instructions)}</textarea></label><label class="field">来源 / 使用说明<input name="source" required value="${h(b.source)}"></label><label class="field">评价标准（每行一项）<textarea name="criteria" required>${h(b.criteria.join('\n'))}</textarea></label><details><summary>绑定教材范围和练习帮助条件</summary>${scopes.map(s=>`<label class="checkline"><input type="checkbox" name="scope" value="${h(s.id)}" ${b.scope_ids?.includes(s.id)?'checked':''}>${h(s.textbook)} · ${h(s.unit)} · 第${s.revision}版</label>`).join('')||'<p>没有单元范围；本次按明确考点试练，不宣称教材同步。</p>'}<label class="field">练习提示（每行一条；带提示不能当独立目标测验）<textarea name="supports">${h((b.supports||[]).join('\n'))}</textarea></label></details><label class="field">原始录音ID（听力必需）<input name="audio_id" value="${h(b.audio_id||'')}" id="academic-audio-id"></label>${d?`<button class="btn text" type="button" data-action="academic-export" data-id="${h(d.id)}">导出这份草稿JSON</button>`:''}<button class="btn ghost" type="button" data-action="academic-audio-upload">导入自己的配套录音</button><p class="small muted">WAV/MP3，最大12MB；填写来源并在审题时完整试听，不自动合成。</p><div id="academic-question-editors">${b.questions.map(academicQuestionEditor).join('')}</div><button class="btn ghost" type="button" data-action="academic-add-question">＋ 加一道题</button><p class="academic-note">保存修改会产生新版本，旧审校不自动沿用。先保存，再逐题审校或开始标明未审的自主练习。</p><button class="btn accent" type="submit">保存候选草稿</button></form>`);}
function academicReadDraftForm(f){const fields=Object.fromEntries(new FormData(f));const qs=Array.from(f.querySelectorAll('.academic-question')).map((el,i)=>{const type=fields['type_'+i],options=academicLines(fields['options_'+i]),key=academicLines(fields['key_'+i]);const traps={};if(academicKinds.includes(type))options.forEach((_,j)=>{const letter=String.fromCharCode(65+j);if(!key.includes(letter))traps[letter]=fields['trap_'+i+'_'+letter]||'语法形式错误';});return {id:'q'+(i+1),type,skill:fields['skill_'+i],material:fields['material_'+i],prompt:fields['prompt_'+i],options,key,evidence:fields['evidence_'+i],explanation:fields['explanation_'+i],traps,points:Number(fields['points_'+i])};});return {title:fields.title,instructions:fields.instructions,goal:fields.goal,source:fields.source,criteria:academicLines(fields.criteria),questions:qs,scope_ids:new FormData(f).getAll('scope'),supports:academicLines(fields.supports),audio_id:fields.audio_id||null};}
async function academicReview(id){const data=(await c7('k12.draft.read',{id},academicPeer())).data;academicDraft=data.record;academicReviewData=data;const d=data.record,candidate=[...data.reviews,...data.candidate_reviews].find(r=>r.draft_hash===d.content_hash),latest=data.candidate_reviews.find(r=>r.draft_hash===d.content_hash);academicDialog('逐题审校：先独立作答，再核对候选',`<form id="academic-review-form" class="local-form"><p>下面的模型或既有审校记录只作参考。请核对题目、可成立答案与替代解，错误选项写清误读路径、排除依据和小练习。</p>${latest?.issues?.length?`<aside class="academic-note"><strong>独立审题发现待处理分歧</strong><ul>${latest.issues.map(x=>`<li>${h(x)}</li>`).join('')}</ul><label class="field">逐项处置理由（若需要修改题目，请退出并另存新版本）<textarea name="resolution_note" required minlength="4" maxlength="2000"></textarea></label></aside>`:''}${d.body.questions.map((q,i)=>{const r=candidate?.questions.find(r=>r.question_id===q.id);return `<fieldset class="academic-question"><legend>${h(q.id)} · ${h(q.skill)}</legend><pre class="academic-material">${h(q.material)}</pre><p><strong>${h(q.prompt)}</strong></p>${q.options.length?`<ol type="A">${q.options.map(o=>`<li>${h(o)}</li>`).join('')}</ol>`:''}<p class="small muted">参考答案：${h(q.key.join(' / ')||'主观题，按原答与量规评阅')}</p><label class="field">我核对的依据<textarea name="basis_${i}" required minlength="4" maxlength="2000">${h(r?.basis||'')}</textarea></label><label class="field">替代解与歧义检查<textarea name="ambiguity_${i}" required minlength="4" maxlength="2000">${h(r?.ambiguity_check||'')}</textarea></label>${academicKinds.includes(q.type)?q.options.map((option,j)=>{const letter=String.fromCharCode(65+j),c=r?.choices.find(c=>c.option===letter);return `<div class="academic-review-choice"><strong>选项${letter}：${h(option)}</strong><label class="checkline"><input name="defensible_${i}_${letter}" type="checkbox" ${c?.defensible?'checked':''}>此项能成立</label><label class="field">成立或误读路径<textarea name="reason_${i}_${letter}" required minlength="4">${h(c?.reasoning||'')}</textarea></label><label class="field">排除依据（错误选项必填）<input name="why_${i}_${letter}" value="${h(c?.why_not||'')}"></label><label class="field">针对这一误读的具体练习（错误选项必填）<input name="next_${i}_${letter}" value="${h(c?.next_step||'')}"></label></div>`;}).join(''):''}</fieldset>`;}).join('')}${d.body.audio_id?`<audio controls src="/api/local/academic/audio/${h(d.body.audio_id)}"></audio><label class="checkline"><input type="checkbox" name="audio_listened" required>我已完整试听原始录音，核对题目与原文配套</label>`:''}<label class="checkline"><input type="checkbox" name="human_review_confirmed" required>我已实际逐题审查，本次以教师身份记录核对结果</label><button class="btn accent" type="submit">保存逐题审校声明</button></form>`);}
async function academicPublish(id){const d=(await c7('k12.draft.read',{id},academicPeer())).data.record;academicDraft=d;academicDialog('布置给当前学生',`<p>${h(d.body.title)} · ${d.body.questions.length}题 · 第${d.revision}版</p><p class="academic-note">先完成逐题审校。目标测验需先确认覆盖，不能在交卷后补录；带提示练习不计独立测量。</p><form id="academic-publish-form"><label class="field">本次用途<select name="mode"><option value="practice">日常练习</option><option value="target">预先声明的独立目标测验</option></select></label><label class="checkline"><input name="confirmed" type="checkbox" required>我已核对当前学生、本次范围和已审版本，确认布置</label><button class="btn accent" type="submit">确认布置给学生</button></form><button class="btn ghost" data-action="academic-target">先确认目标覆盖 →</button>`);}
function academicTarget(){const d=academicDraft;academicDialog('施测前确认目标覆盖',`<form id="academic-target-form" class="local-form"><label class="field">本次目标名称<input name="title" required value="${h(d.body.goal)}"></label><label class="field">目标与题号（每行：目标名称：q1,q2）<textarea name="outcomes" required>${h('本次目标：'+d.body.questions.map(q=>q.id).join(','))}</textarea></label><label class="field">本次自定参考线（%）<input type="number" name="threshold" min="1" max="100" value="80"></label><label class="field">覆盖说明<textarea name="coverage_note" required minlength="4" placeholder="说明各题为何足以检查本次目标；不宣称覆盖全部英语能力"></textarea></label><label class="checkline"><input name="confirmed" type="checkbox" required>我已核对实际题目、目标覆盖和独立条件；参考线仅用于本次试行检查</label><button class="btn accent" type="submit">保存本版本目标覆盖</button></form>`);}
function academicGenerate(){if(!academicRoute)throw Error('先建立路线');academicDialog('用自己的API准备K12候选',`<form id="academic-generate-form" class="local-form"><p>模型读取当前路线和实际范围，不读取教师私注。只保存题目与审题候选，教师确认后才布置；学生自练会标记未审。</p><label class="field">这次集中练什么<textarea name="prompt" required maxlength="2000">${h(academicRoute.goal)}</textarea></label><label class="field">题数<input name="count" type="number" min="1" max="10" value="3"></label><button class="btn accent" type="submit">用我的API生成候选</button></form>`);}
async function academicPoll(id){try{const j=await api('/api/local/jobs/'+id);if(j.status==='completed'){if(view!=='k12')return notify('K12候选已准备好，可到K12草稿列表查看。');await academicHome();notify(j.result.missing?`本批候选已保存，还缺${j.result.missing}题，可在草稿上继续补题。`:'候选已保存，需要实际审题；未自动布置。');if(j.result.mode==='k12_workflow'&&typeof wfContinue==='function')await wfContinue(j.result.draft_id);else await academicReviewOrEdit(j.result.draft_id);return;}if(j.status==='failed')throw Error(j.error);if($('#academic-job-state'))$('#academic-job-state').textContent=j.status==='running'?'正在读取范围并请求自己的模型…':'模型任务已排队…';academicJobTimer=setTimeout(()=>academicPoll(id),1500);}catch(e){notify(e.message,true);if($('#academic-job-state'))$('#academic-job-state').textContent=e.message;}}
async function academicReviewOrEdit(id){return workspaceTeacher()?academicReview(id):academicDraftEditor(id);}
function academicExample(){const code=String(Date.now()).slice(-4);return {title:'原创例题 · 校园通知 '+code,instructions:'先读实际文字，再按题干作答。',goal:'核对主语与通知中的具体信息',source:'团队原创合成示例，非教材/真题，需教师核对',criteria:['回应本题要求','依据可以回查'],scope_ids:[],supports:[],questions:[{id:'q1',type:'grammar_mcq',skill:'be动词主谓一致',material:'I am in Room '+code+'.',prompt:'Choose: I ___ in Room '+code+'.',options:['am','is','are'],key:['A'],evidence:'I am in Room '+code+'.',explanation:'I与am对应。',traps:{B:'语法形式错误',C:'语法形式错误'},points:1}]};}
const academicPreviousShell=shell;
shell=function(html){academicPreviousShell(html);if(view==='task'&&currentTask?.pack.academic)academicEnhanceTask();if(view==='home'&&academicContext?.selection.track==='k12'){$('#workspace-content')?.insertAdjacentHTML('afterbegin','<section class="card"><strong>当前是K12英语路线</strong><p>从实际范围、逐题审校和问题证据开始，不套用托福/雅思出题分支。</p><button class="btn accent" data-action="ws-route" data-route="k12">进入K12英语 →</button></section>');}};
function academicEnhanceTask(){const t=currentTask;if(!t?.pack.academic||$('#academic-task-tools'))return;const meta=t.pack.academic;const text=`英语 / K12 · ${h(academicCatalog?.levels[meta.level]||meta.level)} · ${meta.grade}年级 · ${meta.mode==='target'?'预先声明目标测验':'日常练习'}`;
    $('#workspace-content')?.insertAdjacentHTML('afterbegin',`<section id="academic-task-tools" class="card"><strong>${text}</strong><p class="small muted">原题与帮助条件保留。错项类型不是实际原因；测后追问与勘误不改变原始成绩。</p>${workspaceTeacher()&&t.attempts.length?'<div class="academic-actions"><button class="btn ghost" data-action="academic-problem">问题与验证证据</button><button class="btn ghost" data-action="academic-explain">逐题评阅与双版讲解</button><button class="btn text" data-action="academic-erratum">追加依据勘误</button></div>':''}</section>`);
    const f=$('#work-form');if(f){const sticky=f.querySelector('.sticky-submit')?.outerHTML||'';f.innerHTML=t.pack.items.map((q,i)=>`<fieldset class="academic-question"><legend>第${i+1}题 · ${h(academicCatalog?.types[q.k12_type]||q.k12_type)}</legend>${q.material?`<pre class="academic-material">${h(q.material)}</pre>`:''}${q.kind==='mcq'?question(q,i):`<h3>${h(q.prompt)}</h3><label class="field">我的作答${q.open_response?`<textarea name="${h(q.id)}" maxlength="4000" required></textarea>`:`<input class="input" name="${h(q.id)}" maxlength="4000" required>`}</label>`}</fieldset>`).join('')+`${meta.supports.length?`<aside class="academic-hint"><strong>本次是带提示练习，不作为独立目标测验</strong><ul>${meta.supports.map(s=>`<li>${h(s)}</li>`).join('')}</ul></aside>`:''}<label class="field">本次得到哪些额外帮助？<select id="academic-help" name="academic_help"><option value="未说明">暂未说明</option><option value="none">没有额外帮助（本人声明）</option><option value="得到同伴、教师或模型帮助">得到同伴、教师或模型帮助</option></select></label>`+sticky;if(meta.mode==='target'&&(t.attempts.length||t.local_submissions?.length)){f.querySelectorAll('input,textarea,select,button[type="submit"]').forEach(x=>x.disabled=true);f.insertAdjacentHTML('beforeend','<p class="academic-note">这份目标测验已提交或等待送达，原答不覆盖。需要另用新材料再测。</p>');}}
    if(workspaceTeacher())$('#academic-task-tools')?.insertAdjacentHTML('beforeend',t.pack.audio?`<audio controls src="/api/local/audio/${h(t.id)}"></audio>`:'');
    if(t.academic_feedback?.length){const pub=t.academic_feedback;$('#academic-task-tools')?.insertAdjacentHTML('beforeend',`<div class="academic-work-feedback"><h3>逐题记录与补充反馈</h3>${pub.map(v=>`<article><strong>${h(v.question_id||'')} · ${h(({problem:'问题记录',explanation:'给学生的讲解',score:'教师逐题评阅',erratum:'依据勘误'})[v.kind])}</strong><p>${h(v.student||v.comment||v.observation||v.reason||'')}</p>${v.cause?`<p>${v.state==='supported_cause'?'教师依据补充证据记录的原因':'可能原因，尚待验证'}：${h(v.cause)}</p>`:''}${v.next_step?`<p>下一步：${h(v.next_step)}</p>`:''}${v.kind==='score'?`<p>本题：${v.score}分</p>`:''}${v.invalid_item?'<p>本题已标记无效，原始成绩保留；不用于目标达标判断。</p>':''}</article>`).join('')}</div>`);}
}
const academicOriginalApi=api;
api=async function(path,data,method){if(data&&path.startsWith('/api/local/tasks/')&&path.endsWith('/submit')&&currentTask?.pack.academic){data={...data,learning_conditions:{normal_participation:'本次按已发布K12任务完成；帮助条件由学习者自报',additional_help:$('#academic-help')?.value||'未说明',declaration:'learner_self_report'}};}return academicOriginalApi(path,data,method);};
function academicQuestionChooser(){return `<label class="field">本次题目<select name="question_id" id="academic-work-question">${currentTask.pack.items.map(q=>`<option value="${h(q.id)}">${h(q.id+' · '+q.prompt)}</option>`).join('')}</select></label><div id="academic-work-original"></div>`;}
function academicShowWork(){const id=$('#academic-work-question')?.value,a=currentTask.attempts.at(-1),q=currentTask.pack.items.find(q=>q.id===id);if(!q)return;$('#academic-work-original').innerHTML=`<pre class="academic-material">${h(q.material||'')}</pre><p><strong>${h(q.prompt)}</strong></p><p>学生实际作答：${h(a.answer.answers[id]||'')}</p><p class="small muted">参考答案：${h(q.key?.join(' / ')||'主观评阅')}；预设干扰类型仅作线索。</p>`;}
function academicProblem(){academicDialog('错误表现、原因假设与验证证据',`<form id="academic-problem-form" class="local-form">${academicQuestionChooser()}<label class="field">观察到的实际错法<textarea name="observation" required minlength="4" maxlength="2000"></textarea></label><label class="field">可能原因（可留空）<select name="cause"><option value="">原因未知</option>${academicCatalog.causes.map(c=>`<option>${h(c)}</option>`).join('')}</select></label><label class="field">补充证据来源<select name="evidence_source"><option value="unverified">尚未验证，先保留假设</option><option value="student_explanation">交卷后学生简短解释</option><option value="teacher_observation">教师直接观察</option><option value="diagnostic_check">关联一次实际补充检查</option></select></label><label class="field">实际依据说明<textarea name="evidence_note" maxlength="2000"></textarea></label><label class="field">学生原话（采用学生解释时填写）<textarea name="student_quote" maxlength="1200"></textarea></label><div class="inline-grid"><label class="field">补充检查任务ID<input name="check_task_id"></label><label class="field">补充检查提交ID<input name="check_submission_id"></label></div><label class="checkline"><input name="human_confirmed" type="checkbox">我确认记录的是实际获得的补充证据，不是根据误选猜测</label><p class="small muted">没有补充证据时会保留为假设；不改原成绩，不自动确认长期掌握。</p><button class="btn accent" type="submit">保存本版问题记录</button></form>`);academicShowWork();}
function academicExplain(){academicDialog('逐题评阅与双版本讲解',`<form id="academic-explain-form" class="local-form">${academicQuestionChooser()}<label class="field">给学生的简短讲解<textarea name="student" required minlength="4" maxlength="1000"></textarea></label><label class="field">教师讲稿（只留教师本机）<textarea name="tutor" required minlength="4" maxlength="4000"></textarea></label><label class="field">下一步小练习<input name="next_step" required minlength="4" maxlength="1000"></label><label class="field">原文引用（阅读题必填）<input name="quote" maxlength="2000"></label><details><summary>本题为主观题时，另行记录评分</summary><label class="field">本题分数（不得超原题）<input name="score" type="number" min="0" step=".01"></label><div class="inline-grid">${['内容','交际效果','组织','语言'].map(k=>`<label class="field">写作：${k}（0—3）<input type="number" name="rubric_${k}" min="0" max="3" step="1"></label>`).join('')}</div><label class="field">评分意见<input name="comment" maxlength="2000"></label><label class="field">学生原句证据<input name="evidence" maxlength="2000"></label><p class="small muted">K12写作按四维合计/12折算至原题分值；不是托福/雅思等级。</p></details><label class="checkline"><input name="human_confirmed" type="checkbox" required>我已亲自核对实际作品及相应依据</label><button class="btn accent" type="submit">保存并发送学生版本</button></form>`);academicShowWork();}
function academicErratum(){academicDialog('追加依据勘误，保留原题与原成绩',`<form id="academic-erratum-form" class="local-form">${academicQuestionChooser()}<label class="field">更正后的原文引句<input name="quote" maxlength="2000"></label><label class="field">勘误理由<textarea name="reason" required minlength="4" maxlength="2000"></textarea></label><label class="checkline"><input name="invalid_item" type="checkbox">本题或设备条件有问题，排除其目标达标判断，另安排有效检查</label><label class="checkline"><input name="human_confirmed" type="checkbox" required>我已核对原件；此操作不修改原题答案或学生原答</label><button class="btn accent" type="submit">追加勘误记录</button></form>`);academicShowWork();}
async function academicClassForm(id){const cls=(await c7('k12.class.list')).data.classes.find(c=>c.id===id);academicDialog('班级名单与版本',`<form id="academic-class-form" class="local-form" data-id="${h(cls?.id||'')}" data-revision="${cls?.revision||0}"><label class="field">班级名称<input name="title" required value="${h(cls?.title||'')}"></label>${status.peers.filter(p=>p.role==='student'&&p.state==='active').map(p=>`<label class="checkline"><input type="checkbox" name="peers" value="${h(p.id)}" ${cls?.peers.includes(p.id)?'checked':''}>${h(p.name)}</label>`).join('')}<label class="checkline"><input name="archived" type="checkbox" ${cls?.archived?'checked':''}>归档班级，保留历史任务名单</label><button class="btn accent" type="submit">保存当前名单</button></form>`);}
document.addEventListener('change',async e=>{try{if(['academic-first-subject','academic-first-track'].includes(e.target.id))academicSetupFields();else if(e.target.id==='academic-peer'){selectedPeer=e.target.value;await academicHome();}else if(e.target.id==='academic-route'){localStorage.setItem('academic-route:'+status.device_id+':'+(academicPeer()||'self'),e.target.value);await academicHome();}else if(e.target.id==='academic-work-question')academicShowWork();else if(e.target.id==='academic-import-file'){$('#academic-import-content').value=await e.target.files[0].text();}}catch(error){notify(error.message,true);}});
document.addEventListener('input',e=>{const f=e.target.closest('form[id^="academic-"]');if(f)delete f.dataset.request;});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action^="academic-"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(academicBusy)return;academicBusy=true;b.disabled=true;
    try{const a=b.dataset.action;if(a==='academic-browse')academicBrowseSubject(b.dataset.subject);
        else if(a==='academic-select'){if(recorder?.state==='recording')throw Error('请先停止录音并保存，再切换学科');if(view==='task')await saveDraft();await w8('select',{subject:b.dataset.subject,track:b.dataset.track});await academicLoad();await refreshStatus();selectedPeer='';currentTask=null;academicRoute=null;academicDraft=null;workspaceRows=[];workspacePeople=[];studyMaterial=null;continuityPage=null;files=[];activeJob='';subjectLibraryNotice=null;const route=typeof selfStudyMode==='function'&&selfStudyMode()?'home':!workspaceTeacher()?'tasks':b.dataset.track==='k12'?'k12':b.dataset.track==='study_abroad'?'resources':'home';await workspaceNavigate(route);}
        else if(a==='academic-workspace-new')modal('添加独立学科工作区','<form id="academic-workspace-create-form" class="local-form"><label class="field">学科名称<input class="input" name="name" required maxlength="40" placeholder="例如：物理、计算机科学"></label><p>创建独立资料文件夹和数据库。可以从自己的资料开始，专门教学规则需要另行适配。</p><button class="btn accent" type="submit">创建并进入</button></form>');
        else if(a==='academic-route-new'||a==='academic-route-edit')academicRouteForm(a.endsWith('edit'));
        else if(a==='academic-tab'){academicTab=b.dataset.tab;await academicHome();}
        else if(a==='academic-scope-new'||a==='academic-scope-edit')await academicScopeForm(b.dataset.id);
        else if(a==='academic-scope-check')academicDialog('核对当前词表，保留待确认项','<form id="academic-scope-check-form" class="local-form"><label class="field">待检查文字<textarea name="text" required></textarea></label><label class="field">明确豁免的专名等（每行一个）<textarea name="exempt_words"></textarea></label><button class="btn accent" type="submit">核对提供的范围</button></form><div id="academic-check-result"></div>');
        else if(a==='academic-draft-new')await academicDraftEditor();else if(a==='academic-draft-edit')await academicDraftEditor(b.dataset.id);
        else if(a==='academic-example')await academicDraftEditor(null,academicExample());
        else if(a==='academic-add-question'){$('#academic-question-editors').insertAdjacentHTML('beforeend',academicQuestionEditor(academicEmptyQuestion(document.querySelectorAll('.academic-question').length),document.querySelectorAll('.academic-question').length));}
        else if(a==='academic-independent-review'){const j=await api('/api/local/jobs',{mode:'k12_review',draft_id:b.dataset.id,peer_id:academicPeer()});notify('独立审题已开始：先解题，再看参考，只保存候选。');academicPoll(j.id);}else if(a==='academic-review')await academicReview(b.dataset.id);else if(a==='academic-publish')await academicPublish(b.dataset.id);else if(a==='academic-target')academicTarget();
        else if(a==='academic-self'){const d=(await c7('k12.draft.read',{id:b.dataset.id},academicPeer())).data.record;const p=(await c7('k12.draft.self_practice',{id:d.id,expected_revision:d.revision})).data.record;closeModal();await openTask(p.task_id);}
        else if(a==='academic-retire'){const d=(await c7('k12.draft.read',{id:b.dataset.id},academicPeer())).data.record;await c7('k12.bank.retire',{id:d.id,expected_revision:d.revision},academicPeer());await academicHome();}
        else if(a==='academic-generate')academicGenerate();
        else if(a==='academic-next'){const rep=(await c7('k12.report',{route_id:academicRoute.id},academicPeer())).data;if(rep.pending_reviews||rep.invalid_questions)throw Error('先处理当前待评作品或无效题，再安排有效新练习。');academicGenerate();$('#academic-generate-form textarea').value=rep.next.action+'。当前目标：'+academicRoute.goal+'。实际记录：'+rep.problems.map(p=>p.state+'：'+p.observation+'；可能原因：'+(p.cause||'未知')).join('；').slice(0,1100)+'。仅准备少量有区分作用的新题，不把一种练习形式用于所有困难。';}
        else if(a==='academic-bank-compose'){const result=(await c7('k12.bank.compose',{id:b.dataset.id,expected_revision:Number(b.dataset.revision),title:academicRoute.title+' · 未见题组题'},academicPeer())).data.record;await academicDraftEditor(result.id);notify('已组成新候选，需核对新组合后重新审题。');}
        else if(a==='academic-bank-pick')academicDialog('按考点查当前学生未见题','<form id="academic-bank-form"><label class="field">考点（每行一项，可留空）<textarea name="skills"></textarea></label><label class="field">需要题数<input name="count" type="number" min="1" max="80" value="5"></label><button class="btn accent" type="submit">查找未见库存并记录缺口</button></form><div id="academic-bank-result"></div>');
        else if(a==='academic-problem')academicProblem();else if(a==='academic-explain')academicExplain();else if(a==='academic-erratum')academicErratum();
        else if(a==='academic-notification'){await c7('k12.notifications.read',{id:b.dataset.id});await openTask(b.dataset.task);}
        else if(a==='academic-open-work'){await openTask(b.dataset.id);}
        else if(a==='academic-import')academicDialog('先预览K12 JSON草稿，再确认保存','<button class="btn ghost" data-action="academic-template">下载可填写JSON模板</button><form id="academic-import-form" class="local-form"><label class="field">选择JSON草稿文件<input type="file" id="academic-import-file" accept=".json"></label><label class="field">草稿数组<textarea name="content" id="academic-import-content" required maxlength="500000"></textarea></label><p class="small muted">字段按手动草稿结构；导入不代表审题。可以下载原创示例模板，或导出已保存的草稿作为格式示例。</p><button class="btn accent" type="submit">生成导入预览</button></form><div id="academic-import-result"></div>');
        else if(a==='academic-template')academicDownload([academicExample()],'K12-original-template.json');
        else if(a==='academic-export'){const d=(await c7('k12.draft.read',{id:b.dataset.id},academicPeer())).data.record;academicDownload([{...d.body,scope_ids:[],audio_id:null}],'K12-draft-'+d.id+'.json');notify('已导出草稿；本机范围和录音ID未跨设备复制，须重新关联。');}
        else if(a==='academic-import-commit'){await c7('k12.import.commit',{id:b.dataset.id,preview_hash:b.dataset.hash},academicPeer(),b.dataset.key||uid());closeModal();await academicHome();}
        else if(a==='academic-audio-upload'){const f=$('#academic-draft-form');academicDraft={...(academicDraft||{}),_unsaved:academicReadDraftForm(f)};academicDialog('导入配套原始录音','<form id="academic-audio-form" class="local-form"><label class="field">录音文件（WAV/MP3，12MB以内）<input name="file" type="file" accept="audio/wav,audio/mpeg,.wav,.mp3" required></label><label class="field">来源及使用说明<input name="source" required maxlength="1000"></label><label class="checkline"><input name="human_voice" type="checkbox">我声明此录音来自真人；系统不能仅凭文件认证</label><button class="btn accent" type="submit">导入并返回草稿</button></form>');}
        else if(a==='academic-class-new'||a==='academic-class-edit')await academicClassForm(b.dataset.id);
        else if(a==='academic-class-report'){const rep=(await c7('k12.class.report',{id:b.dataset.id})).data;academicDialog('班级任务报告',`<p>${h(rep.meaning)}</p><table class="academic-table"><tr><th>学生</th><th>状态</th><th>客观核对</th></tr>${rep.rows.map(row=>`<tr><td>${h(status.peers.find(p=>p.id===row.peer_id)?.name||'授权已变化')}</td><td>${h(({not_submitted:'未交',pending_review:'待评',submitted:'已有提交',failed:'布置失败',authorization_revoked:'已解除授权'})[row.state]||row.state)}</td><td>${row.objective?row.objective.score+'/'+row.objective.total:'不计为零分'}</td></tr>`).join('')}</table>`);}
        else if(a==='academic-class-assign'){const c=(await c7('k12.class.list')).data.classes.find(c=>c.id===b.dataset.id),ds=(await c7('k12.bank.list',{route_id:academicRoute.id},academicPeer())).data.records;academicDialog('冻结本次名单，逐人检查后布置',`<form id="academic-class-assign-form" data-id="${h(c.id)}" data-revision="${c.revision}"><p>只布置日常练习；目标测验须逐人确认。跨学生的教材范围不自动复制，条件不足会明确列失败。</p><label class="field">源已审草稿<select name="source">${ds.map(d=>`<option value="${h(d.id)}" data-revision="${d.revision}">${h(d.body.title)} · 第${d.revision}版</option>`).join('')}</select></label><label class="checkline"><input name="confirmed" type="checkbox" required>我已选择班级和适用草稿，确认按冻结名单布置</label><button class="btn accent" type="submit">确认批量布置 / 重试失败项</button></form><div id="academic-class-result"></div>`);}
        else if(a==='academic-group-candidates'){const data=(await c7('k12.class.candidates',{route_id:academicRoute.id},academicPeer())).data;academicDialog('证据不足不凑组',`<p>${h(data.meaning)}</p>${data.candidates.map(c=>`<p>${h(status.peers.find(p=>p.id===c.peer_id)?.name||'学生')} · ${c.evidence.length}份目标测验记录；需核对同一范围与独立条件。</p>`).join('')||'<p>目前没有满足条件的候选。</p>'}`);}
    }catch(error){notify(error.message,true);}finally{academicBusy=false;if(b.isConnected)b.disabled=false;}
},true);
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id.startsWith('academic-'))return;e.preventDefault();if(academicBusy)return;academicBusy=true;const b=f.querySelector('[type="submit"]');if(b)b.disabled=true;const obj=Object.fromEntries(new FormData(f));f.dataset.request||=uid();const key=f.dataset.request,peer=academicPeer();
    try{
        if(f.id==='academic-workspace-create-form'){const created=(await w8('create',{name:obj.name},key)).data.subject;await w8('select',{subject:created.id});await academicLoad();await refreshStatus();selectedPeer='';closeModal();await workspaceNavigate('home');}
        else if(f.id==='academic-route-form'){const p={...obj,grade:Number(obj.grade),weekly_sessions:Number(obj.weekly_sessions),scope_order:Number(obj.scope_order||1),archived:f.elements.archived?.checked||false,expected_revision:Number(f.dataset.revision)};if(f.dataset.id)p.id=f.dataset.id;const result=(await c7('route.save',p,peer,key)).data.record;localStorage.setItem('academic-route:'+status.device_id+':'+(peer||'self'),result.id);closeModal();await academicHome();}
        else if(f.id==='academic-scope-form'){const p={...obj,route_id:academicRoute.id,order:Number(obj.order),words:academicLines(obj.words),phrases:academicLines(obj.phrases),grammar:academicLines(obj.grammar),complete:f.elements.complete.checked,content_reviewed:f.elements.content_reviewed?.checked||false,material_id:obj.material_id||null,expected_revision:Number(f.dataset.revision)};if(f.dataset.id)p.id=f.dataset.id;await c7('scope.save',p,peer,key);closeModal();await academicHome();}
        else if(f.id==='academic-scope-check-form'){const scopes=(await c7('scope.list',{route_id:academicRoute.id},peer)).data.records;const check=(await c7('scope.check',{route_id:academicRoute.id,text:obj.text,scope_ids:scopes.map(s=>s.id),exempt_words:academicLines(obj.exempt_words)},peer)).data.check;$('#academic-check-result').innerHTML=`<p class="academic-note">${check.ok===null?'范围可靠性不足，结论保持待确认':check.ok?'在提供的词表中未发现未匹配项':'存在未匹配词，须结合词形与语境核对'}</p><p>${h(check.unmatched_words.join('、')||'无未匹配词')}</p><p>${h(check.meaning)}</p>`;}
        else if(f.id==='academic-draft-form'){const p={route_id:academicRoute.id,body:academicReadDraftForm(f),expected_revision:Number(f.dataset.revision)};if(f.dataset.id)p.id=f.dataset.id;await c7('k12.draft.save',p,peer,key);closeModal();await academicHome();notify('候选草稿已保存；修改产生新版本，需重新审题。');}
        else if(f.id==='academic-review-form'){if(!f.elements.human_review_confirmed.checked)throw Error('先实际审题，再确认');const d=academicDraft,questions=d.body.questions.map((q,i)=>({question_id:q.id,basis:obj['basis_'+i],ambiguity_check:obj['ambiguity_'+i],choices:academicKinds.includes(q.type)?q.options.map((_,j)=>{const l=String.fromCharCode(65+j);return {option:l,defensible:f.elements['defensible_'+i+'_'+l].checked,reasoning:obj['reason_'+i+'_'+l],why_not:obj['why_'+i+'_'+l],next_step:obj['next_'+i+'_'+l]};}):[]}));await c7('k12.draft.review',{id:d.id,expected_revision:d.revision,draft_hash:d.content_hash,questions,resolution_note:obj.resolution_note||'',human_review_confirmed:true,audio_listened:f.elements.audio_listened?.checked||false},peer,key);closeModal();await academicHome();notify('逐题审校已记录；布置需另行确认。');}
        else if(f.id==='academic-publish-form'){if(!f.elements.confirmed.checked)throw Error('先核对本次学生与版本');const d=academicDraft,p=(await c7('k12.draft.publish',{id:d.id,expected_revision:d.revision,mode:obj.mode,human_review_confirmed:true},peer,key)).data.record;closeModal();await openTask(p.task_id);notify('任务已保存并加入发送队列。');}
        else if(f.id==='academic-target-form'){const outcomes={};for(const line of academicLines(obj.outcomes)){const parts=line.split(/[：:]/);if(parts.length!==2)throw Error('每行按“目标：q1,q2”填写');outcomes[parts[0].trim()]=parts[1].split(/[,，]/).map(s=>s.trim()).filter(Boolean);}const d=academicDraft;await c7('k12.target.confirm',{id:d.id,expected_revision:d.revision,draft_hash:d.content_hash,target:{title:obj.title,outcomes,threshold:Number(obj.threshold)/100,coverage_note:obj.coverage_note},human_review_confirmed:f.elements.confirmed.checked},peer,key);await academicPublish(d.id);notify('目标覆盖已保存到本版本；尚未布置。');}
        else if(f.id==='academic-generate-form'){const j=await api('/api/local/jobs',{mode:'k12_generate',route_id:academicRoute.id,prompt:obj.prompt,count:Number(obj.count),peer_id:peer});closeModal();$('#workspace-content')?.insertAdjacentHTML('afterbegin','<p class="academic-note" id="academic-job-state">K12候选任务已排队。可以继续查看资料；未自动审题或布置。</p>');academicPoll(j.id);}
        else if(f.id==='academic-bank-form'){const selection=(await c7('k12.bank.pick',{route_id:academicRoute.id,count:Number(obj.count),skills:academicLines(obj.skills)},peer,key)).data.record;$('#academic-bank-result').innerHTML=`<p>需要${selection.requested}题，找到${selection.selected.length}道未见题，还缺${selection.missing}题。</p><p>${h(selection.next)}</p>${!selection.missing&&selection.selected.length?`<button class="btn accent" data-action="academic-bank-compose" data-id="${h(selection.id)}" data-revision="${selection.revision}">将选中的未见题组成新草稿</button>`:''}${Array.from(new Set(selection.selected.map(q=>q.draft_id))).map(id=>`<button class="btn ghost" data-action="academic-draft-edit" data-id="${h(id)}">查看对应已审草稿</button>`).join('')}`;}
        else if(f.id==='academic-import-form'){const p=(await c7('k12.import.preview',{route_id:academicRoute.id,content:obj.content},peer,key)).data.record;$('#academic-import-result').innerHTML=p.errors.length?`<p>${p.errors.map(e=>'第'+e.row+'份：'+h(e.message)).join('<br>')}</p>`:`<p>${p.drafts.length}份候选草稿可导入，之后仍须审题。</p><button class="btn accent" data-action="academic-import-commit" data-id="${h(p.id)}" data-hash="${p.content_hash}" data-key="${uid()}">确认保存候选草稿</button>`;}
        else if(f.id==='academic-audio-form'){const data=new FormData(f);data.set('speech_origin',f.elements.human_voice.checked?'human_declared':'unverified');data.delete('human_voice');const result=(await api('/api/local/academic/media',data)).record;const original=academicDraft?._unsaved,id=academicDraft?.id;original.audio_id=result.id;await academicDraftEditor(id,original);notify('录音已导入。请保存新草稿，并在审题时完整试听。');}
        else if(['academic-problem-form','academic-explain-form'].includes(f.id)){const a=currentTask.attempts.at(-1),work={task_id:currentTask.id,submission_id:a.id,question_id:obj.question_id},pub=currentTask.academic_feedback||[];
            if(f.id==='academic-problem-form'){const prior=pub.find(v=>v.kind==='problem'&&v.submission_id===a.id&&v.question_id===obj.question_id);await c7('k12.problem.record',{...work,...obj,expected_revision:prior?.revision||0,human_confirmed:f.elements.human_confirmed.checked,check_task_id:obj.check_task_id||null,check_submission_id:obj.check_submission_id||null},peer,key);}
            else{const prior=pub.find(v=>v.kind==='explanation'&&v.submission_id===a.id&&v.question_id===obj.question_id);await c7('k12.explain.save',{...work,expected_revision:prior?.revision||0,student:obj.student,tutor:obj.tutor,next_step:obj.next_step,quote:obj.quote,human_confirmed:f.elements.human_confirmed.checked},peer,key+'-explain');if(obj.score!==''){const oldScore=pub.find(v=>v.kind==='score'&&v.submission_id===a.id&&v.question_id===obj.question_id);const q=currentTask.pack.items.find(q=>q.id===obj.question_id),rubric={};if(['writing','writing_task'].includes(q.k12_type))for(const k of ['内容','交际效果','组织','语言'])rubric[k]=Number(obj['rubric_'+k]);await c7('k12.score.record',{...work,expected_revision:oldScore?.revision||0,score:Number(obj.score),rubric,comment:obj.comment,evidence:obj.evidence,human_confirmed:f.elements.human_confirmed.checked},peer,key+'-score');}}
            closeModal();await openTask(work.task_id);notify('本机记录已保存，学生可见部分加入发送队列；原始成绩保留。');}
        else if(f.id==='academic-erratum-form'){await c7('k12.evidence.correct',{task_id:currentTask.id,question_id:obj.question_id,quote:obj.quote,reason:obj.reason,invalid_item:f.elements.invalid_item.checked,human_confirmed:f.elements.human_confirmed.checked},peer,key);const id=currentTask.id;closeModal();await openTask(id);}
        else if(f.id==='academic-class-form'){const p={title:obj.title,peers:new FormData(f).getAll('peers'),archived:f.elements.archived.checked,expected_revision:Number(f.dataset.revision)};if(f.dataset.id)p.id=f.dataset.id;await c7('k12.class.save',p,null,key);closeModal();await academicHome();}
        else if(f.id==='academic-class-assign-form'){const selected=f.elements.source.selectedOptions[0];if(!selected)throw Error('先有一份已审草稿');const data=(await c7('k12.class.assign',{id:f.dataset.id,expected_revision:Number(f.dataset.revision),source_draft_id:obj.source,source_revision:Number(selected.dataset.revision)},null,key)).data.batch;$('#academic-class-result').innerHTML=data.entries.map(e=>`<p>${h(status.peers.find(p=>p.id===e.peer_id)?.name||'学生')}：${e.task_id?'已保存并排队':h(e.error)}</p>`).join('');}
    }catch(error){notify(error.message,true);}finally{academicBusy=false;if(b?.isConnected)b.disabled=false;}
});

function academicDownload(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

const academicPreviousResults=results;
results=function(task){
    if(!task.pack.academic)return academicPreviousResults(task);
    if(!task.attempts?.length)return '';
    return `<section class="card"><h2>原始作答与核对历史</h2>${task.attempts.slice().reverse().map((a,i)=>`<details ${i===0?'open':''}><summary>第${task.attempts.length-i}次原答 · ${a.automatic?.pending?.length?'含待评主观题':'已有客观核对'}</summary><p class="small muted">原始客观核对：${a.automatic?.score??'—'} / ${a.automatic?.total??'—'}。未评主观题未计零分；逐题人工评分另外保留，不覆盖此原始记录。</p>${task.pack.items.map(q=>{const row=a.automatic?.items?.find(r=>r.id===q.id);return `<div class="result-item ${row?.correct===true?'good':row?.correct===false?'bad':''}"><strong>${h(q.id)} · ${row?.correct==null?'主观回答，待查看教师逐题评阅':row.correct?'符合本题参考':'本次需要核对'}</strong><p>${h(q.prompt)}</p><p>原始作答：${h(a.answer?.answers?.[q.id]||'未记录')}</p><p class="small muted">参考：${h((row?.accepted||q.key||[]).join(' / ')||'按本题量规评阅')}<br>依据：${h(row?.evidence||q.evidence||'')}<br>${h(row?.explanation||q.explanation||'')}</p></div>`;}).join('')}${a.evaluation?.comment?`<div class="local-banner"><strong>${a.review_history?.length?'教师反馈':'设备核对记录'}</strong><p>${h(a.evaluation.comment)}</p><p>下一步：${h(a.evaluation.next_step||'')}</p></div>`:''}${workspaceTeacher()?`<button class="btn accent" data-action="feedback" data-id="${h(a.id)}">AI预审 / 人工评阅</button>`:''}</details>`).join('')}</section>`;
};
const academicPreviousGuide=guide;
guide=function(){academicPreviousGuide();$('#workspace-content')?.insertAdjacentHTML('afterbegin',`<section class="card"><span class="eyebrow">源码工程版 / 独立学科工作区</span><h2>先选择学科，再进入对应教学链</h2><p>从“学科与路线”选择并进入一个工作区；资料、作业、反馈、札记与复习按学科独立保存。切换其他学科后才能查看其内容。英语工作区内再选择K12或留学路线。K12：建立学段/年级路线 → 登记实际范围 → 准备草稿 → 独立审题与教师核对 → 明确布置 → 学生原答 → 逐题评阅、验证与新题再测。</p><p>新增学科会创建独立目录；身份、模型API配置与师生配对共用。没有API也能使用原创示例。历史未归属作业在只读历史工作区查看；其他学科暂用通用资料学习，专业规则需另行适配。</p><button class="btn accent" data-action="ws-route" data-route="academic">选择学科与路线 →</button></section>`);};

const academicPreviousEnhanceTask=academicEnhanceTask;
academicEnhanceTask=function(){academicPreviousEnhanceTask();const t=currentTask;if(!t?.pack.academic)return;const stimulus=$('.stimulus');if(stimulus&&!t.pack.stimulus)stimulus.textContent=t.pack.audio?'请先播放实际录音，再按逐题要求作答。':'本次原文与作答要求按逐题内容查看。';if(workspaceTeacher()&&!$('#academic-teacher-original'))$('#academic-task-tools')?.insertAdjacentHTML('beforeend',`<details id="academic-teacher-original"><summary>查看冻结原题、参考答案与目标</summary><p>目标：${h(t.pack.companion_plan?.goal||'')}</p>${t.pack.items.map(q=>`<article class="academic-question"><strong>${h(q.id+' · '+q.prompt)}</strong><pre class="academic-material">${h(q.material||'')}</pre>${q.options?.length?`<ol type="A">${q.options.map(o=>`<li>${h(o)}</li>`).join('')}</ol>`:''}<p>参考：${h((q.key||[]).join(' / ')||'主观题，按量规评阅')}<br>依据：${h(q.evidence||'')}</p></article>`).join('')}</details>`);};
